MP="py -3.13 <your-picture-maker>/make-picture.py"
STY="Simple whiteboard marker line drawing in black and white: black marker outlines only on a pure white background, monochrome, all areas left white, one clean uniform thick black outline weight, friendly simple doodle, very few details, no texture marks, no crumb dots, no shading, no hatching, no text, the object centred with a wide white margin around it, no frame."
NEG="colour, colored, coloured fill, brown, tan, orange, yellow, green, red, lettuce, leaves, tomato, cheese, ham, shading, hatching, cross-hatching, stippling, dots, texture lines, grey tones, gradient, photo, realistic, 3d render, text, letters, words, numbers, watermark, logo, signature, blurry, low quality, sketchy messy lines, thin lines, frame, border, paper edge"
O=assets_work/wb
$MP "$STY Subject, top view from directly above: a rectangular cutting board, on it a square slice of sandwich bread with a domed top edge, a big chef's knife lying on top of the sandwich exactly along its diagonal from the top-left corner to the bottom-right corner, the knife handle sticking out past the top-left corner." $O/cut_d --n 4 --seed 531 --negative "$NEG"
$MP "$STY Subject: two triangle sandwich halves on a round plate seen from slightly above, slightly apart from each other, each half is two layers of bread with one plain smooth layer of peanut butter between them drawn as a simple band between two smooth lines." $O/halves_d --n 4 --seed 631 --negative "$NEG"
